  const request = JSON.parse(readFileSync('./fixtures/roomplan/bedroom-primary/capture-request.json','utf8'));
  const capture = service.postRoomPlanCapture(request);
  const token = JSON.parse(capture.qr_payload).handoff_token;
  service.redeemHandoff({ handoff_token: token });
  const scene = service.getScene(capture.scene_id);
  if (!scene) throw new Error('no scene');
  const bed = scene.snapshot.state.room.objects.find((o) => o.class === 'bed');
  if (!bed) throw new Error('no bed');
  const preview = service.createScenePreview(capture.scene_id, {
    request_id: 'preview-1',
    idempotency_key: 'preview-key-1',
    expected_scene_version: scene.head.current_scene_version,
    explanation: 'move bed slightly',
    ops: [{ op:'move_object', object_id: bed.object_id, target_position: { ...bed.pose.position, x: bed.pose.position.x + 0.1 }, include_children: false }]
  });
  console.log('preview', preview.preview.preview_id, preview.validation_summary.hard_violations.length);
  const applied = service.applyScenePreview(capture.scene_id, {
    preview_id: preview.preview.preview_id,
    apply_token: preview.preview.apply_token,
    canonical_plan_hash: preview.preview.canonical_plan_hash,
    expected_scene_version: scene.head.current_scene_version,
    idempotency_key: 'apply-key-1'
  });
  console.log('applied', applied.applied_scene_version, applied.scene.head.undo_base_snapshot_id);
  const undone = service.undoLastChange(capture.scene_id, { expected_scene_version: applied.applied_scene_version, idempotency_key: 'undo-key-1' });
  console.log('undo', undone.applied_scene_version, undone.scene.head.undo_base_snapshot_id);
} finally { rmSync(dir,{recursive:true,force:true}); }
