export const REASON_CODE_VALUES = [
  "AUTH_REQUIRED",
  "SCENE_ACCESS_DENIED",
  "HANDOFF_EXPIRED",
  "HANDOFF_ALREADY_USED",
  "AMBIGUOUS_TARGET",
